samples.raw_completion:
// Concatenate the input vectors together and split them up into several
// output vectors. The input vectors are a, b, c, d, e, and f, for a total
// of 30 bits of input. The output vectors are w, x, y, and z, for 32 bits
// of output. The output should be a concatenation of the input vectors
// followed by two 1 bits (the two 1 bits should be in the LSB positions).
module TopModule(
    input [4:0] a,
    input [4:0] b,
    input [4:0] c,
    input [4:0] d,
    input [4:0] e,
    input [4:0] f,
    output [7:0] w,
    output [7:0] x,
    output [7:0] y,
    output [7:0] z
);
    wire [29:0] combined = {a, b, c, d, e, f};
    assign {w, x, y, z} = {combined, 2'b11};
endmodule

// Concatenate inputs, split into 8-bit words and append two 1 bits.
module TopModule(
